const WERKZEUG = 'storage_gdrive.get_file';
const ADAPTER_ID = 'storage_gdrive';
const alle = $input.all();
if (alle.length !== 1) {
  throw new Error('adp_storage_gdrive_invalid_input: genau ein Aufruf je Ausfuehrung erwartet, erhalten ' + alle.length);
}
const e = alle[0].json;
const p = (e.payload && typeof e.payload === 'object' && !Array.isArray(e.payload)) ? e.payload : null;
const fehler = [];
if (!/^[a-z][a-z0-9_]{2,63}$/.test(String(e.context_id || ''))) fehler.push('context_id fehlt oder hat kein gueltiges Format');
if (e.tool_id !== WERKZEUG) fehler.push('tool_id passt nicht zu diesem Adapter');
if (!/^act_[A-Za-z0-9_]{6,64}$/.test(String(e.action_id || ''))) fehler.push('action_id fehlt oder ist ungueltig');
let einlesen = true;
let grenze = null;
if (!p) {
  fehler.push('payload fehlt');
} else {
  const erlaubt = ['context_id', 'adapter_id', 'file_external_id', 'include_content', 'max_size_mb'];
  const fremd = Object.keys(p).filter(function (k) { return erlaubt.indexOf(k) === -1; });
  if (fremd.length > 0) fehler.push('payload enthaelt unzulaessige Felder: ' + fremd.join(', '));
  if (p.context_id !== e.context_id) fehler.push('context_mismatch: payload.context_id weicht vom Aufrufkontext ab');
  if (p.adapter_id !== ADAPTER_ID) fehler.push('adapter_id passt nicht zu diesem Adapter');
  if (!/^[A-Za-z0-9_-]{10,200}$/.test(String(p.file_external_id || ''))) fehler.push('file_external_id fehlt oder ist ungueltig');
  if (p.include_content !== undefined) {
    if (typeof p.include_content !== 'boolean') fehler.push('include_content ist kein Wahrheitswert');
    else einlesen = p.include_content;
  }
  if (p.max_size_mb !== undefined) {
    if (!Number.isInteger(p.max_size_mb) || p.max_size_mb < 1 || p.max_size_mb > 200) fehler.push('max_size_mb ausserhalb 1 bis 200');
    else grenze = p.max_size_mb;
  }
}
const basis = { adapter_id: ADAPTER_ID, tool_id: WERKZEUG, context_id: e.context_id || null, action_id: e.action_id || null, trace_id: e.trace_id || null };
if (fehler.length > 0) {
  return [{ json: Object.assign({ route: 'invalid', fehler: fehler }, basis) }];
}
return [{ json: Object.assign({ route: e.dry_run === true ? 'dry_run' : e.context_id, file_external_id: p.file_external_id, include_content: einlesen, max_size_mb: grenze }, basis) }];

const e = $input.first().json;
// TS-10: Ohne Fehlerliste kommt der Eintrag aus dem Ausweichausgang der Kontextweiche.
const fehler = (Array.isArray(e.fehler) && e.fehler.length > 0) ? e.fehler : ['context_id ohne Kontextweiche'];
return [{ json: { status: 'error', adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, write_outcome: 'none', checked_stage: 'input', error: { error_class: 'validation', error_code: 'invalid_input', retryable: false, message: fehler.join('; ') }, trace_id: e.trace_id } }];

const e = $('Eingabe pruefen').first().json;
const f = $input.first().json || {};
const roh = JSON.stringify(f.error || f).slice(0, 2000);
let klasse = 'unknown';
let code = 'db_error';
let wiederholbar = false;
if (/42501|permission denied/i.test(roh)) { klasse = 'permission'; code = 'permission_denied'; }
else if (/timeout|timed out|ETIMEDOUT/i.test(roh)) { klasse = 'timeout'; code = 'db_timeout'; wiederholbar = true; }
else if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|terminat|connection/i.test(roh)) { klasse = 'transient_network'; code = 'db_unreachable'; wiederholbar = true; }
return [{ json: { status: 'error', adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, write_outcome: 'none', checked_stage: 'config', error: { error_class: klasse, error_code: code, retryable: wiederholbar, message: roh.slice(0, 300) }, trace_id: e.trace_id } }];

// Kontextwurzel aus den Dokumenteinstellungen (1.1b-E1). Der Verweis zeigt auf eine
// n8n-Variable; ihr Wert ist die reine Ordner-ID. Fehlt etwas: Abbruch (fail closed).
const e = $('Eingabe pruefen').first().json;
const basis = { adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, trace_id: e.trace_id };
const abbruch = function (klasse, code, text) {
  return [{ json: Object.assign({ weiter: false, status: 'error', write_outcome: 'none', checked_stage: 'config', error: { error_class: klasse, error_code: code, retryable: false, message: text } }, basis) }];
};
const zeilen = $input.all().map(function (x) { return x.json; }).filter(function (z) { return z && z.storage_adapter_id; });
if (zeilen.length !== 1) return abbruch('validation', 'config_missing', 'keine eindeutigen Dokumenteinstellungen fuer den Kontext');
const z = zeilen[0];
if (z.storage_adapter_id !== e.adapter_id) return abbruch('validation', 'adapter_context_mismatch', 'Speicheradapter des Kontexts ist ' + z.storage_adapter_id);
const m = /^env:([A-Z][A-Z0-9_]{3,63})$/.exec(String(z.context_root_ref || ''));
if (!m) return abbruch('validation', 'config_unresolved', 'Kontextwurzel ohne gueltigen Variablenverweis');
let wert = null;
try { wert = $vars[m[1]]; } catch (x) { wert = null; }
wert = (typeof wert === 'string') ? wert.trim() : '';
if (!/^[A-Za-z0-9_-]{10,200}$/.test(wert)) return abbruch('validation', 'config_unresolved', 'Variable ' + m[1] + ' fehlt oder ist keine reine Ordner-ID');
const grenzeMb = e.max_size_mb || Number(z.max_file_size_mb);
if (!Number.isInteger(grenzeMb) || grenzeMb < 1) return abbruch('validation', 'config_missing', 'Groessengrenze fehlt');
return [{ json: Object.assign({ weiter: true, file_external_id: e.file_external_id, include_content: e.include_content, max_bytes: grenzeMb * 1024 * 1024, root_id: wert }, basis) }];

return $input.all().map(function (x) {
  const j = Object.assign({}, x.json);
  delete j.weiter;
  return { json: j };
});

// Fehler des Speicherdienstes. Wiederholbar nur transient_network, rate_limited, timeout
// (retry_policy im Register). Die Stufe zeigt, bis wohin gelesen wurde.
const e = $('Eingabe pruefen').first().json;
const f = $input.first().json || {};
const roh = JSON.stringify(f.error || f).slice(0, 2000);
let stufe = 'metadata';
try {
  if ($('Wurzel pruefen').isExecuted) stufe = 'content';
  else if ($('Metadaten pruefen').isExecuted) stufe = 'root';
} catch (x) { stufe = 'unknown'; }
const s = /(?:^|[^0-9])([45][0-9][0-9])(?:[^0-9]|$)/.exec(roh);
const status = s ? Number(s[1]) : null;
let klasse = 'unknown';
let code = 'provider_error';
let wiederholbar = false;
if (/timeout|timed out|ETIMEDOUT|ESOCKETTIMEDOUT|ECONNABORTED/i.test(roh)) { klasse = 'timeout'; code = 'provider_timeout'; wiederholbar = true; }
else if (status === 429 || (status === 403 && /rateLimit|RateLimitExceeded|quotaExceeded/i.test(roh))) { klasse = 'rate_limited'; code = 'rate_limited'; wiederholbar = true; }
else if (status === 404) { klasse = 'not_found'; code = 'not_found'; }
else if (status === 401) { klasse = 'auth_failed'; code = 'auth_failed'; }
else if (status === 403) { klasse = 'permission'; code = 'permission_denied'; }
else if (status !== null && status >= 500) { klasse = 'transient_network'; code = 'provider_unavailable'; wiederholbar = true; }
else if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|socket hang up/i.test(roh)) { klasse = 'transient_network'; code = 'provider_unreachable'; wiederholbar = true; }
return [{ json: { status: 'error', adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, write_outcome: 'none', checked_stage: stufe, provider_status: status, error: { error_class: klasse, error_code: code, retryable: wiederholbar, message: roh.slice(0, 300) }, trace_id: e.trace_id } }];

// Grundpruefung der Metadaten. Typ und Groesse werden erst nach der Wurzelpruefung
// bewertet: eine Datei ausserhalb der Wurzel liefert immer outside_context_root.
const k = $('Konfiguration aufloesen').first().json;
const m = $input.first().json || {};
const basis = { adapter_id: k.adapter_id, tool_id: k.tool_id, context_id: k.context_id, action_id: k.action_id, trace_id: k.trace_id };
const abbruch = function (klasse, code, text) {
  return [{ json: Object.assign({ weiter: false, status: 'error', write_outcome: 'none', checked_stage: 'metadata', error: { error_class: klasse, error_code: code, retryable: false, message: text } }, basis) }];
};
if (m.id !== k.file_external_id) return abbruch('consistency', 'metadata_mismatch', 'Metadaten gehoeren nicht zur angefragten Datei');
if (m.driveId) return abbruch('permission', 'outside_context_root', 'Objekt liegt in einer geteilten Ablage');
const eltern = Array.isArray(m.parents) ? m.parents : [];
if (eltern.length !== 1) return abbruch('permission', 'outside_context_root', 'Objekt hat ' + eltern.length + ' Elternordner');
const mod = m.modifiedTime ? new Date(m.modifiedTime) : null;
return [{ json: Object.assign({ weiter: true, root_id: k.root_id, max_bytes: k.max_bytes, include_content: k.include_content, parent_id: eltern[0],
  meta: { file_external_id: m.id, filename: m.name, mime_type: m.mimeType, size_raw: (m.size === undefined ? null : m.size), trashed: m.trashed === true,
          modified_at: (mod && !isNaN(mod.getTime())) ? mod.toISOString().replace(/[.][0-9]{3}Z$/, 'Z') : null,
          provider_sha256: m.sha256Checksum ? String(m.sha256Checksum).toLowerCase() : null } }, basis) }];

// P1-T-22 / 1.1-A11: Aufstieg ueber die Elternordner bis zur Kontextwurzel.
// Grundlage ist die Ordnerliste des Kontos (nur IDs und Elternverweise, keine Namen).
const s = $('Metadaten pruefen').first().json;
const basis = { adapter_id: s.adapter_id, tool_id: s.tool_id, context_id: s.context_id, action_id: s.action_id, trace_id: s.trace_id };
const abbruch = function (stufe, klasse, code, text) {
  return [{ json: Object.assign({ weiter: false, status: 'error', write_outcome: 'none', checked_stage: stufe, error: { error_class: klasse, error_code: code, retryable: false, message: text } }, basis) }];
};
const seiten = $input.all().map(function (x) { return x.json || {}; });
const eltern = {};
for (const sp of seiten) {
  for (const f of (Array.isArray(sp.files) ? sp.files : [])) {
    if (f && f.id) eltern[f.id] = Array.isArray(f.parents) ? f.parents : [];
  }
}
const letzte = seiten.length > 0 ? seiten[seiten.length - 1] : {};
if (seiten.length === 0 || letzte.nextPageToken) return abbruch('root', 'consistency', 'root_check_incomplete', 'Ordnerliste unvollstaendig, Wurzelpruefung nicht moeglich');
let akt = s.parent_id;
let innen = false;
const gesehen = {};
for (let schritt = 0; schritt < 50 && akt; schritt++) {
  if (akt === s.root_id) { innen = true; break; }
  if (gesehen[akt]) break;
  gesehen[akt] = true;
  const p = eltern[akt];
  if (!p || p.length !== 1) break;
  akt = p[0];
}
if (!innen) return abbruch('root', 'permission', 'outside_context_root', 'Objekt liegt ausserhalb der Kontextwurzel');
const m = s.meta;
if (m.mime_type === 'application/vnd.google-apps.shortcut') return abbruch('type', 'permission', 'shortcut_not_allowed', 'Verknuepfungen werden nicht aufgeloest');
if (m.mime_type === 'application/vnd.google-apps.folder') return abbruch('type', 'validation', 'not_a_file', 'Objekt ist ein Ordner');
if (/^application\/vnd\.google-apps\./.test(String(m.mime_type || ''))) return abbruch('type', 'validation', 'no_binary_content', 'Google-eigenes Format ohne herunterladbare Bytes');
if (m.trashed) return abbruch('type', 'validation', 'file_trashed', 'Datei liegt im Papierkorb');
const groesse = Number(m.size_raw);
if (m.size_raw === null || !Number.isInteger(groesse) || groesse < 0) return abbruch('type', 'validation', 'size_unknown', 'Dateigroesse nicht verfuegbar');
if (groesse > s.max_bytes) return abbruch('type', 'validation', 'file_too_large', 'Datei ueberschreitet die Groessengrenze');
if (String(m.filename || '').length === 0 || String(m.filename).length > 300) return abbruch('type', 'validation', 'filename_invalid', 'Dateiname fehlt oder ist laenger als 300 Zeichen');
return [{ json: Object.assign({ weiter: true, include_content: s.include_content, meta: Object.assign({}, m, { size_bytes: groesse }) }, basis) }];

// Inhaltshash selbst bilden (AA-B2), Groesse und Anbieterpruefsumme abgleichen.
// Der Inhalt bleibt ein n8n-Binaerdatum und wird nirgends gespeichert (AA-B5).
const crypto = require('crypto');
const s = $('Wurzel pruefen').first().json;
const m = s.meta;
const basis = { adapter_id: s.adapter_id, tool_id: s.tool_id, context_id: s.context_id, action_id: s.action_id, trace_id: s.trace_id };
const fehler = function (code, text) {
  return [{ json: Object.assign({ status: 'error', write_outcome: 'none', checked_stage: 'content', error: { error_class: 'consistency', error_code: code, retryable: false, message: text } }, basis) }];
};
const it = $input.first();
if (!it || !it.binary || !it.binary.data) return fehler('content_missing', 'kein Dateiinhalt erhalten');
const puffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (puffer.length !== m.size_bytes) return fehler('size_mismatch', 'geladene Groesse ' + puffer.length + ' weicht von den Metadaten ab');
const hash = crypto.createHash('sha256').update(puffer).digest('hex');
if (m.provider_sha256 && m.provider_sha256 !== hash) return fehler('checksum_mismatch', 'Pruefsumme des Speicherdienstes weicht ab');
const ergebnis = { file_external_id: m.file_external_id, filename: m.filename, mime_type: m.mime_type, size_bytes: m.size_bytes, content_hash: 'sha256:' + hash, provider_status: 200 };
if (m.modified_at) ergebnis.modified_at = m.modified_at;
if (s.include_content) ergebnis.content_ref = 'data';
const aus = { json: Object.assign({ status: 'ok', write_outcome: 'none', verification_method: 'provider_status', result: ergebnis,
  observed: { provider_status: 200, content_hash: 'sha256:' + hash, provider_checksum: m.provider_sha256 ? 'match' : 'not_available' } }, basis) };
if (s.include_content) aus.binary = { data: it.binary.data };
return [aus];
